package local.ondemand;
import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Uses exact movie-linked YouTube IDs; no search, stream extraction or playback-history writes. */
final class MovieTrailer {
 static String videoId(String value){if(value.matches("[A-Za-z0-9_-]{11}"))return value;try{Uri u=Uri.parse(value);if(!"https".equals(u.getScheme()))return "";String host=u.getHost(),id="";if("youtu.be".equals(host))id=u.getLastPathSegment();else if("www.youtube.com".equals(host)||"youtube.com".equals(host)||"m.youtube.com".equals(host)){if("/watch".equals(u.getPath()))id=u.getQueryParameter("v");else if(u.getPath()!=null&&u.getPath().startsWith("/embed/"))id=u.getLastPathSegment();}return id!=null&&id.matches("[A-Za-z0-9_-]{11}")?id:"";}catch(Exception ignored){return "";}}
 static final class Link {final String id;final int rank;Link(String id,int rank){this.id=id;this.rank=rank;}}
 static List<Link> links(JSONObject movie){Map<String,Link> found=new LinkedHashMap<>();for(String field:new String[]{"trailers","trailerStreams"}){JSONArray list=movie.optJSONArray(field);if(list==null)continue;for(int i=0;i<list.length();i++){JSONObject t=list.optJSONObject(i);if(t==null)continue;String kind=t.optString("type","Trailer");if(!kind.equalsIgnoreCase("Trailer"))continue;String site=t.optString("site","YouTube");if(!site.equalsIgnoreCase("YouTube"))continue;String id=videoId(t.optString("ytId",t.optString("source",t.optString("key",t.optString("url","")))));if(id.isEmpty())continue;String lang=t.optString("iso_639_1",t.optString("lang",""));int rank=(t.optBoolean("official")?100:0)+(lang.equalsIgnoreCase("en")?20:lang.isEmpty()?10:0);Link prior=found.get(id);if(prior==null||rank>prior.rank)found.put(id,new Link(id,rank));}}List<Link> out=new ArrayList<>(found.values());out.sort((a,b)->Integer.compare(b.rank,a.rank));return out;}
 static Intent intent(String id,String pkg){return new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.youtube.com/watch").buildUpon().appendQueryParameter("v",id).build()).setPackage(pkg).putExtra("finish_on_ended",true).putExtra("force_fullscreen",true);}
 static void open(MainActivity a,String id){for(String pkg:new String[]{"com.google.android.youtube.tv","com.google.android.youtube"})try{a.trailerReturnId=a.videoId;a.startActivity(intent(id,pkg));return;}catch(ActivityNotFoundException|SecurityException ignored){}a.trailerReturnId="";Toast.makeText(a,"YouTube could not open. Check that YouTube is installed and enabled.",Toast.LENGTH_LONG).show();}
 static Button add(MainActivity a,JSONObject movie,LinearLayout column){List<Link> links=links(movie);if(links.isEmpty())return null;final String[] selected={links.get(0).id};Button b=a.button("▶ Watch trailer",()->open(a,selected[0]));b.setTag("selection:trailer");b.setTextSize(11);b.setSingleLine(true);b.setPadding(a.dp(6),0,a.dp(6),0);b.setContentDescription("Watch movie trailer in YouTube");b.setOnClickListener(v->{b.requestFocus();open(a,selected[0]);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,a.dp(24));p.topMargin=a.dp(5);column.addView(b,p);final int token=a.generation;a.artwork.submit(()->{boolean allRemoved=true;String valid="";for(int i=0;i<Math.min(3,links.size());i++){if(token!=a.generation)return;java.net.HttpURLConnection c=null;try{String url="https://www.youtube.com/oembed?url="+java.net.URLEncoder.encode("https://www.youtube.com/watch?v="+links.get(i).id,"UTF-8")+"&format=json";c=(java.net.HttpURLConnection)new java.net.URL(url).openConnection();c.setConnectTimeout(2500);c.setReadTimeout(3500);c.setRequestProperty("User-Agent","Mozilla/5.0 PiCinema/1.0");int code=c.getResponseCode();if(code==200){valid=links.get(i).id;allRemoved=false;break;}if(code!=404&&code!=410)allRemoved=false;}catch(Exception ignored){allRemoved=false;}finally{if(c!=null)c.disconnect();}}final String winner=valid;final boolean removed=allRemoved;a.clock.post(()->{if(token!=a.generation||a.isFinishing())return;if(!winner.isEmpty())selected[0]=winner;if(removed){if(b.hasFocus()){View art=a.rows.findViewWithTag("selection:artwork");if(art!=null)art.requestFocus();}b.setVisibility(View.GONE);}});});return b;}
}
